create table agency_archive_checklist(tenant_id text not null,package_id text not null,item_key text not null,version bigint not null default 1,disposition text not null check(disposition in ('included','not_applicable','missing')),snapshot_json jsonb not null,updated_by text not null,updated_at timestamptz not null default now(),primary key(tenant_id,package_id,item_key),foreign key(tenant_id,package_id) references agency_packages(tenant_id,id));
create table agency_archive_snapshots(id text primary key,tenant_id text not null,package_id text not null,ordinal int not null,previous_id text,snapshot_json jsonb not null,frozen_hash text not null,source_fingerprint text not null,complete boolean not null,reason text not null,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id),unique(tenant_id,package_id,ordinal),foreign key(tenant_id,package_id) references agency_packages(tenant_id,id));
create table agency_completion_events(id text primary key,tenant_id text not null,package_id text not null,dimension text not null,snapshot_json jsonb not null,frozen_hash text not null,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,package_id) references agency_packages(tenant_id,id));
